// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC721/IERC721.sol";
import "@openzeppelin/contracts/interfaces/IERC2981.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/security/Pausable.sol";
import "@openzeppelin/contracts/security/ReentrancyGuard.sol";
import "@openzeppelin/contracts/utils/introspection/IERC165.sol";

/**
 * @title NFTDutchAuctionMarket
 * @author Expert Solidity Engineer
 * @notice A secure marketplace for ERC721 NFTs using Dutch auctions on EVM-compatible chains like BaseCAMP.
 * It supports ERC2981 royalties, a configurable marketplace fee, and emergency pausing.
 * Sellers list NFTs which are held by the contract. The price linearly decreases over a set duration.
 * Buyers can purchase the NFT at any time during the auction for the current price.
 * Proceeds are distributed to the seller, royalty recipient (if applicable), and the marketplace treasury.
 */
contract NFTDutchAuctionMarket is Ownable, Pausable, ReentrancyGuard {
    /**
     * @dev Represents a single Dutch auction for an NFT.
     * @param seller The address of the user who created the auction.
     * @param nft The address of the ERC721 contract.
     * @param tokenId The ID of the NFT being auctioned.
     * @param startPrice The initial price of the NFT in wei.
     * @param endPrice The final price of the NFT in wei if the auction completes.
     * @param startTime The Unix timestamp when the auction begins.
     * @param duration The duration of the auction in seconds.
     * @param payoutAddress The address to which the seller's proceeds will be sent.
     * @param supportsRoyalties A flag indicating if the seller wishes to honor ERC2981 royalties.
     * @param settled A flag indicating if the auction has been settled (either purchased or cancelled).
     */
    struct Auction {
        address seller;
        IERC721 nft;
        uint256 tokenId;
        uint256 startPrice;
        uint256 endPrice;
        uint256 startTime;
        uint256 duration;
        address payoutAddress;
        bool supportsRoyalties;
        bool settled;
    }

    // --- State Variables ---

    mapping(uint256 => Auction) private _auctions;
    uint256 private _auctionIdCounter;

    uint256 private _marketplaceFeeBps;
    address private _treasury;
    uint256 private _feesAccrued;

    uint256 public constant BPS_MAX = 10000;
    bytes4 private constant _INTERFACE_ID_ERC2981 = type(IERC2981).interfaceId;

    // --- Events ---

    event AuctionCreated(
        uint256 auctionId,
        address indexed seller,
        address indexed nft,
        uint256 indexed tokenId,
        uint256 startPrice,
        uint256 endPrice,
        uint256 startTime,
        uint256 duration
    );

    event AuctionSettled(
        uint256 indexed auctionId,
        address indexed buyer,
        uint256 price,
        uint256 fee,
        uint256 royalty
    );

    event AuctionCancelled(uint256 indexed auctionId);
    event FeesWithdrawn(address indexed treasury, uint256 amount);
    event FeeUpdated(uint256 newFeeBps);
    event TreasuryUpdated(address newTreasury);

    // --- Constructor ---

    /**
     * @dev Sets up the contract with an initial treasury address and marketplace fee.
     * @param initialTreasury The address where marketplace fees will be sent.
     * @param initialFeeBps The marketplace fee in basis points (1% = 100).
     */
    constructor(address initialTreasury, uint256 initialFeeBps) {
        require(initialTreasury != address(0), "Treasury address cannot be zero");
        require(initialFeeBps <= BPS_MAX, "Fee cannot exceed 100%");
        _treasury = initialTreasury;
        _marketplaceFeeBps = initialFeeBps;
    }

    // --- Admin Functions ---

    /**
     * @dev Updates the marketplace fee. Can only be called by the owner.
     * @param newFeeBps The new fee in basis points.
     */
    function setMarketplaceFeeBps(uint256 newFeeBps) external onlyOwner {
        require(newFeeBps <= BPS_MAX, "Fee cannot exceed 100%");
        _marketplaceFeeBps = newFeeBps;
        emit FeeUpdated(newFeeBps);
    }

    /**
     * @dev Updates the treasury address. Can only be called by the owner.
     * @param newTreasury The new address for the treasury.
     */
    function setTreasury(address newTreasury) external onlyOwner {
        require(newTreasury != address(0), "Treasury address cannot be zero");
        _treasury = newTreasury;
        emit TreasuryUpdated(newTreasury);
    }

    /**
     * @dev Allows the owner to withdraw accrued marketplace fees to the treasury.
     */
    function withdrawFees() external onlyOwner {
        uint256 amount = _feesAccrued;
        require(amount > 0, "No fees to withdraw");
        _feesAccrued = 0;
        _safePay(_treasury, amount);
        emit FeesWithdrawn(_treasury, amount);
    }

    /**
     * @dev Pauses the contract, preventing new auctions, purchases, and cancellations.
     * Can only be called by the owner.
     */
    function pause() external onlyOwner {
        _pause();
    }

    /**
     * @dev Unpauses the contract. Can only be called by the owner.
     */
    function unpause() external onlyOwner {
        _unpause();
    }

    // --- View Functions ---

    /**
     * @dev Retrieves the details of a specific auction.
     * @param auctionId The ID of the auction.
     * @return The Auction struct.
     */
    function getAuction(uint256 auctionId) external view returns (Auction memory) {
        return _auctions[auctionId];
    }

    /**
     * @dev Calculates the current price of an NFT in a Dutch auction.
     * @param auctionId The ID of the auction.
     * @return The current price in wei.
     */
    function getCurrentPrice(uint256 auctionId) public view returns (uint256) {
        Auction memory auction = _auctions[auctionId];
        require(auction.seller != address(0), "Auction does not exist");

        if (block.timestamp < auction.startTime) {
            return auction.startPrice;
        }

        uint256 elapsedTime = block.timestamp - auction.startTime;
        if (elapsedTime >= auction.duration) {
            return auction.endPrice;
        }

        uint256 priceDrop = auction.startPrice - auction.endPrice;
        uint256 priceReduction = (priceDrop * elapsedTime) / auction.duration;
        return auction.startPrice - priceReduction;
    }

    /**
     * @dev Returns the current marketplace fee in basis points.
     */
    function marketplaceFeeBps() external view returns (uint256) {
        return _marketplaceFeeBps;
    }

    /**
     * @dev Returns the current treasury address.
     */
    function treasury() external view returns (address) {
        return _treasury;
    }

    /**
     * @dev Returns the total fees currently accrued and available for withdrawal.
     */
    function feesAccrued() external view returns (uint256) {
        return _feesAccrued;
    }

    // --- Core Functions ---

    /**
     * @dev Creates a new Dutch auction for an ERC721 NFT.
     * The sender must own the NFT and have approved this contract to transfer it.
     * @param nftAddress The address of the ERC721 contract.
     * @param tokenId The ID of the NFT to auction.
     * @param startPrice The starting price in wei.
     * @param endPrice The ending price in wei.
     * @param duration The auction duration in seconds.
     * @param startTime The Unix timestamp for when the auction starts.
     * @param payoutAddress The address for receiving seller proceeds.
     * @param supportsRoyalties Whether to check for and pay ERC2981 royalties.
     */
    function createAuction(
        address nftAddress,
        uint256 tokenId,
        uint256 startPrice,
        uint256 endPrice,
        uint256 duration,
        uint256 startTime,
        address payoutAddress,
        bool supportsRoyalties
    ) external whenNotPaused {
        require(duration > 0, "Duration must be positive");
        require(startPrice >= endPrice, "Start price must be >= end price");
        require(startTime >= block.timestamp, "Start time must be in the future");
        require(payoutAddress != address(0), "Payout address cannot be zero");

        IERC721 nft = IERC721(nftAddress);
        require(nft.ownerOf(tokenId) == msg.sender, "You are not the owner of this NFT");

        // The contract takes custody of the NFT for the auction duration.
        nft.transferFrom(msg.sender, address(this), tokenId);

        uint256 auctionId = _auctionIdCounter;
        _auctions[auctionId] = Auction({
            seller: msg.sender,
            nft: nft,
            tokenId: tokenId,
            startPrice: startPrice,
            endPrice: endPrice,
            startTime: startTime,
            duration: duration,
            payoutAddress: payoutAddress,
            supportsRoyalties: supportsRoyalties,
            settled: false
        });

        _auctionIdCounter++;

        emit AuctionCreated(
            auctionId,
            msg.sender,
            nftAddress,
            tokenId,
            startPrice,
            endPrice,
            startTime,
            duration
        );
    }

    /**
     * @dev Buys an NFT from an active auction.
     * The transaction value must be at least the current auction price.
     * Excess ETH will be refunded.
     * @param auctionId The ID of the auction to buy from.
     */
    function buy(uint256 auctionId) external payable whenNotPaused nonReentrant {
        Auction storage auction = _auctions[auctionId];

        require(auction.seller != address(0), "Auction does not exist");
        require(!auction.settled, "Auction already settled");
        require(block.timestamp >= auction.startTime, "Auction has not started");

        uint256 price = getCurrentPrice(auctionId);
        require(msg.value >= price, "Not enough ETH sent");

        // Checks-Effects-Interactions Pattern: Effect
        auction.settled = true;

        // Interactions
        uint256 feeAmount = 0;
        uint256 royaltyAmount = 0;
        uint256 remainingPayout = price;

        // 1. Marketplace Fee
        if (_marketplaceFeeBps > 0) {
            feeAmount = (price * _marketplaceFeeBps) / BPS_MAX;
            if (feeAmount > 0) {
                _feesAccrued += feeAmount;
                remainingPayout -= feeAmount;
            }
        }

        // 2. ERC2981 Royalty (if supported and enabled)
        if (auction.supportsRoyalties) {
            if (IERC165(address(auction.nft)).supportsInterface(_INTERFACE_ID_ERC2981)) {
                try IERC2981(address(auction.nft)).royaltyInfo(auction.tokenId, price) returns (address receiver, uint256 royaltyValue) {
                    if (receiver != address(0) && royaltyValue > 0) {
                        // Per EIP-2981, royaltyInfo returns the absolute amount to be paid.
                        if (royaltyValue <= remainingPayout) {
                            royaltyAmount = royaltyValue;
                            remainingPayout -= royaltyAmount;
                            _safePay(receiver, royaltyAmount);
                        }
                    }
                } catch {
                    // Royalty info call failed or NFT doesn't support it, proceed without royalty.
                }
            }
        }

        // 3. Seller's Proceeds
        if (remainingPayout > 0) {
            _safePay(auction.payoutAddress, remainingPayout);
        }

        // 4. Refund excess ETH to buyer
        if (msg.value > price) {
            _safePay(msg.sender, msg.value - price);
        }

        // 5. Transfer NFT to buyer
        auction.nft.safeTransferFrom(address(this), msg.sender, auction.tokenId);

        emit AuctionSettled(auctionId, msg.sender, price, feeAmount, royaltyAmount);
    }

    /**
     * @dev Cancels an auction. Can only be called by the seller before the auction starts.
     * The NFT is returned to the seller.
     * @param auctionId The ID of the auction to cancel.
     */
    function cancelAuction(uint256 auctionId) external whenNotPaused {
        Auction storage auction = _auctions[auctionId];

        require(auction.seller == msg.sender, "Only the seller can cancel");
        require(!auction.settled, "Auction already settled");
        require(block.timestamp < auction.startTime, "Cannot cancel after start");

        // Mark as settled to prevent further actions
        auction.settled = true;

        // Return the NFT to the seller
        auction.nft.safeTransferFrom(address(this), auction.seller, auction.tokenId);

        emit AuctionCancelled(auctionId);
    }

    // --- Internal Functions ---

    /**
     * @dev Internal function to safely send ETH.
     * @param to The recipient address.
     * @param value The amount of ETH in wei to send.
     */
    function _safePay(address to, uint256 value) internal {
        if (value == 0) return;
        (bool success, ) = to.call{value: value}("");
        require(success, "ETH transfer failed");
    }
}

